// Idiomatic Stream Check (Input Validation)
int value;
std::cin >> value;

if (!std::cin) {
    std::cerr << "Input error.\n";
    // Clear error flags (failbit/badbit)
    std::cin.clear();
    // Discard remaining input in buffer
    std::cin.ignore(std::numeric_limits<std::streamsize>::max(), '\n');
}


// File Open and Iteration Check
std::ifstream file("data.txt");

if (!file.is_open()) {
    throw std::runtime_error("File not found.");
}

std::string line;
while (std::getline(file, line)) {
    // Process line
}

// Check state after iteration loop
if (file.bad()) {
    std::cerr << "Fatal I/O error (Device failure).\n";
} else if (file.fail() && !file.eof()) {
    std::cerr << "Read failed (Format error).\n";
}
